    bounceMax = eff(3);
    on_off = eff(4);
    $bm_rt = n = 0;
    if ($bm_sum(numKeys, 0)) {
        $bm_rt = n = nearestKey(time).index;
        if ($bm_sum(key(n).time, time)) {
            n--;
