            vu = $bm_sum(vl, 0) ? normalize(v) : [
                0,
                0,
                0
            ];
        } else {
            vu = $bm_sum(v, 0) ? -1 : 1;
        }
        tCur = 0;
        segDur = $bm_div($bm_mul(2, vl), gravity);
        tNext = segDur;
        numberOfBounces = 1;
        while (tNext < t && numberOfBounces <= bounceMax) {
            vl *= elastic;
            segDur *= elastic;
            tCur = tNext;
            tNext = $bm_sum(segDur);
            numberOfBounces++;
        }
        if ($bm_sum(numberOfBounces, bounceMax)) {
            delta = $bm_sub(t, tCur);
            $bm_rt = inOutExp = $bm_mul($bm_mul(vu, delta), $bm_sub(vl, $bm_div($bm_mul(gravity, delta), 2)));
            if ($bm_sum(on_off, 1)) {
                $bm_rt = value = $bm_sub(value, inOutExp);
            } else {
                $bm_rt = value = $bm_sum(value, inOutExp);
            }
        } else {
            $bm_rt = value = value;
        }
    } else {
        $bm_rt = value = value;
    }
} catch (e$$4) {
    $bm_rt = value = value;
}

